const shareText = `I just learned 10 life-saving skills in about 10 minutes. Here's the short version:\n\n${lessons.map((l, i) => `${i + 1}. ${l.title}: ${l.remember}`).join("\n")}\n\nPlease learn them too, then pass it on.`;
