:root {
  --paper: #f7f3ec;
  --paper-2: #efe8dc;
  --card: #fffdf9;
  --ink: #1d1b19;
  --ink-2: #57514a;
  --line: #e1d8c9;
  --red: #c8102e;
  --red-soft: #fbe6e8;
  --green: #1f7a4d;
  --green-soft: #e1f2e8;
  --blue: #1d5fa8;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Times New Roman", serif;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --radius: 16px;
  --shadow: 0 1px 2px rgba(40, 30, 20, .06), 0 8px 24px rgba(40, 30, 20, .06);
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 17px/1.55 var(--sans);
}
body.noscroll { overflow: hidden; }
h1, h2, h3 { font-family: var(--serif); line-height: 1.15; margin: 0; }
a { color: inherit; }
button { font: inherit; color: inherit; }
:focus-visible { outline: 3px solid var(--blue); outline-offset: 2px; }

/* ---------- buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .4em;
  background: var(--ink); color: #fff; border: 2px solid var(--ink);
  border-radius: 999px; padding: .6em 1.2em; font-weight: 600;
  text-decoration: none; cursor: pointer; transition: transform .1s, background .2s;
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(1px); }
.btn.big { font-size: 1.1rem; padding: .8em 1.5em; }
.btn.small { font-size: .9rem; padding: .45em 1em; }
.btn.ghost { background: transparent; color: var(--ink); }
.btn.next { margin-left: .6em; }

/* ---------- hero ---------- */
.hero {
  min-height: 100vh; display: flex; align-items: center;
  padding: 4rem 1.25rem 3rem;
  background:
    radial-gradient(1200px 500px at 85% -10%, rgba(200, 16, 46, .10), transparent 60%),
    radial-gradient(900px 500px at -10% 110%, rgba(31, 122, 77, .08), transparent 60%),
    var(--paper);
}
.hero-inner { max-width: 1040px; margin: 0 auto; width: 100%; }
.eyebrow { font-size: .8rem; letter-spacing: .06em; text-transform: uppercase; color: var(--ink-2); margin: 0 0 1.2rem; }
.hero h1 { font-size: clamp(2.6rem, 7vw, 5.2rem); font-weight: 700; letter-spacing: -.02em; }
.hero h1 em { color: var(--red); font-style: italic; }
.lede { font-size: clamp(1.15rem, 2.1vw, 1.45rem); max-width: 42ch; margin: 1.4rem 0 0; }
.lede.soft { color: var(--ink-2); font-size: clamp(1rem, 1.6vw, 1.15rem); max-width: 56ch; }
.hero-actions { display: flex; flex-wrap: wrap; gap: .8rem; margin: 2rem 0 2.6rem; }
.hero-index {
  list-style: none; padding: 0; margin: 0;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 0 1.5rem;
  border-top: 1px solid var(--line);
}
.hero-index li { border-bottom: 1px solid var(--line); }
.hero-index a { display: flex; gap: .8em; padding: .6em 0; text-decoration: none; font-size: .95rem; }
.hero-index a:hover { color: var(--red); }
.ix { font-family: var(--serif); color: var(--red); font-variant-numeric: tabular-nums; }

/* ---------- top bar ---------- */
.topbar {
  position: sticky; top: 0; z-index: 20;
  display: flex; align-items: center; gap: 1rem;
  padding: .5rem 1rem;
  background: rgba(247, 243, 236, .92); backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
  transform: translateY(-100%); transition: transform .25s; margin-bottom: -53px;
}
.topbar.show { transform: none; }
.brand { font-family: var(--serif); font-weight: 700; white-space: nowrap; }
.dots { display: flex; gap: 4px; flex: 1; justify-content: center; }
.dot {
  width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center;
  font-size: 15px; text-decoration: none; background: var(--card); border: 2px solid var(--line);
  filter: grayscale(1); opacity: .6; transition: all .2s;
}
.dot.here { border-color: var(--ink); opacity: 1; }
.dot.on { filter: none; opacity: 1; border-color: var(--green); background: var(--green-soft); }
.tally { font-size: .9rem; color: var(--ink-2); white-space: nowrap; }
.count { font-weight: 700; color: var(--ink); }
.sos {
  background: var(--red); color: #fff; border: 0; border-radius: 999px;
  padding: .4em .9em; font-weight: 700; font-size: .9rem; cursor: pointer; white-space: nowrap;
}

/* ---------- lessons ---------- */
main { padding: 1rem 1.25rem 0; }
.lesson {
  max-width: 1040px; margin: 3.5rem auto; padding: 2rem;
  background: var(--card); border: 1px solid var(--line); border-radius: 24px; box-shadow: var(--shadow);
  scroll-margin-top: 70px; position: relative; transition: border-color .4s;
}
.lesson.learned { border-color: #9fd1b5; }
.lesson-head { display: flex; gap: 1.2rem; align-items: flex-start; margin-bottom: 1.6rem; }
.lesson-num {
  font-family: var(--serif); font-size: 3.2rem; line-height: 1; color: var(--red);
  font-variant-numeric: tabular-nums; min-width: 2ch;
}
.lesson.learned .lesson-num { color: var(--green); }
.lesson h2 { font-size: clamp(1.6rem, 3.4vw, 2.3rem); }
.icon { font-size: .8em; }
.stat { margin: .6rem 0 0; color: var(--ink-2); font-size: 1.05rem; max-width: 62ch; }
.lesson-body { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }
.lesson h3 { font-size: 1.15rem; margin-bottom: .8rem; display: flex; align-items: center; gap: .6rem; }
.steps { padding-left: 1.3em; margin: 0; }
.steps li { margin: 0 0 .7em; padding-left: .2em; }
.steps li::marker { font-family: var(--serif); font-weight: 700; color: var(--red); }
.steps b { font-weight: 650; }
.steps.big { font-size: 1.15rem; }
.note {
  background: var(--paper); border-left: 4px solid var(--blue); border-radius: 8px;
  padding: .8em 1em; font-size: .95rem; color: var(--ink-2); margin: 1rem 0 0;
}
.practice {
  background: var(--paper); border-radius: var(--radius); padding: 1.4rem; align-self: start;
  border: 1px dashed var(--line);
}
.badge {
  font-family: var(--sans); font-size: .72rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase;
  background: var(--ink); color: #fff; padding: .2em .6em; border-radius: 999px;
}
.learned .badge { background: var(--green); }
.practice-lead { margin: 0 0 1rem; font-weight: 600; }
.lesson-foot { margin-top: 1.5rem; text-align: right; }
.next-link { font-weight: 600; text-decoration: none; color: var(--ink-2); }
.next-link:hover { color: var(--red); }

/* ---------- feedback ---------- */
.feedback { margin: .9rem 0 0; min-height: 1.5em; font-size: .97rem; }
.feedback.good { color: var(--green); }
.feedback.bad { color: var(--red); }
.feedback.big { font-size: 1.1rem; font-weight: 600; }
.shake { animation: shake .35s; }
@keyframes shake { 20%, 60% { transform: translateX(-5px); } 40%, 80% { transform: translateX(5px); } }

/* ---------- quiz ---------- */
.q-count { font-size: .78rem; text-transform: uppercase; letter-spacing: .06em; color: var(--ink-2); margin: 1rem 0 .2rem; }
.quiz:first-child .q-count { margin-top: 0; }
.q { font-weight: 600; margin: 0 0 .8rem; }
.options { display: grid; gap: .5rem; }
.option {
  text-align: left; background: var(--card); border: 2px solid var(--line); border-radius: 12px;
  padding: .7em .9em; cursor: pointer; transition: border-color .15s, background .15s;
}
.option:hover:not(:disabled) { border-color: var(--ink); }
.option.right { border-color: var(--green); background: var(--green-soft); }
.option.wrong { border-color: #e8a7ae; background: var(--red-soft); opacity: .8; cursor: not-allowed; }
.options.solved .option:not(.right) { opacity: .45; pointer-events: none; }

/* ---------- sorter ---------- */
.sorter { display: grid; gap: .5rem; }
.sort-row {
  display: grid; grid-template-columns: 1fr auto; gap: .3rem .8rem; align-items: center;
  background: var(--card); border: 2px solid var(--line); border-radius: 12px; padding: .55em .8em;
}
.sort-row.is-yes { border-color: var(--green); background: var(--green-soft); }
.sort-row.is-no { border-color: #e8a7ae; background: var(--red-soft); }
.sort-btns { display: flex; gap: .3rem; }
.chip {
  border: 2px solid var(--line); background: var(--paper); border-radius: 999px;
  padding: .25em .8em; cursor: pointer; font-weight: 600; font-size: .88rem;
}
.chip.yes:hover { border-color: var(--green); }
.chip.no:hover { border-color: var(--red); }
.sort-row.done .chip:not(.picked) { visibility: hidden; }
.chip.picked.yes { background: var(--green); color: #fff; border-color: var(--green); }
.chip.picked.no { background: var(--red); color: #fff; border-color: var(--red); }
.why { grid-column: 1 / -1; margin: 0; font-size: .88rem; }
.why:empty { display: none; }
.why.good { color: var(--green); }
.why.bad { color: var(--red); }

/* ---------- sequence ---------- */
.seq-placed { padding-left: 1.4em; margin: 0 0 .8rem; min-height: .5em; }
.seq-placed li { background: var(--green-soft); border-radius: 8px; padding: .35em .6em; margin-bottom: .35rem; animation: pop .25s; }
.seq-placed li::marker { font-weight: 700; color: var(--green); }
.seq-pool { display: flex; flex-wrap: wrap; gap: .45rem; }
.seq-chip {
  background: var(--card); border: 2px solid var(--line); border-radius: 12px; padding: .5em .8em;
  cursor: pointer; text-align: left;
}
.seq-chip:hover { border-color: var(--ink); }
@keyframes pop { from { transform: scale(.96); opacity: 0; } }

/* ---------- dialogue ---------- */
.thread { display: flex; flex-direction: column; gap: .5rem; margin-bottom: 1rem; }
.bubble { max-width: 85%; padding: .6em .9em; border-radius: 18px; animation: pop .25s; }
.bubble.them { background: #fff; border: 1px solid var(--line); align-self: flex-start; border-bottom-left-radius: 4px; }
.bubble.me { background: var(--blue); color: #fff; align-self: flex-end; border-bottom-right-radius: 4px; }
.choices { display: grid; gap: .5rem; }

/* ---------- emergency number ---------- */
.num-widget { text-align: center; margin-bottom: 1.4rem; padding-bottom: 1.2rem; border-bottom: 1px solid var(--line); }
.num-select {
  font: inherit; width: 100%; padding: .6em .8em; border-radius: 12px; border: 2px solid var(--line); background: var(--card);
}
.num-big { font-family: var(--serif); font-size: 4.5rem; font-weight: 700; color: var(--red); line-height: 1.1; margin-top: .6rem; letter-spacing: .04em; }
.num-note { margin: .2rem 0 0; color: var(--ink-2); font-size: .95rem; }

/* ---------- CPR ---------- */
.cpr-main { display: flex; gap: 1.2rem; align-items: center; }
.chest {
  flex: none; width: 150px; height: 150px; border-radius: 50%;
  background: radial-gradient(circle at 50% 40%, #fff, #f1e3d6); border: 3px solid var(--ink);
  display: grid; place-items: center; cursor: pointer; user-select: none; touch-action: manipulation;
  box-shadow: 0 8px 0 #2d2a26; transition: box-shadow .08s, transform .08s; color: var(--red);
}
.chest.pushed { animation: push .22s ease-out; }
@keyframes push { 30% { transform: translateY(7px) scale(.97); box-shadow: 0 1px 0 #2d2a26; } }
.hands { display: block; line-height: 0; }
.chest-label { font-weight: 800; letter-spacing: .12em; font-size: .85rem; color: var(--ink); margin-top: -1.6rem; }
.cpr-side { flex: 1; min-width: 0; }
.bpm { display: flex; align-items: baseline; gap: .4rem; }
.bpm-n { font-family: var(--serif); font-size: 2.8rem; font-weight: 700; font-variant-numeric: tabular-nums; }
.bpm-u { color: var(--ink-2); font-size: .9rem; }
.gauge { position: relative; height: 14px; border-radius: 7px; background: #e9e1d3; margin: .4rem 0 1.6rem; }
.zone { position: absolute; left: 40%; width: 20%; top: 0; bottom: 0; background: #9fd1b5; border-radius: 4px; }
.gauge.ok .zone { background: var(--green); }
.needle { position: absolute; top: -5px; width: 4px; height: 24px; background: var(--ink); border-radius: 2px; left: 0; transform: translateX(-50%); transition: left .15s; }
.tick { position: absolute; top: 18px; font-size: .72rem; color: var(--ink-2); transform: translateX(-50%); }
.metro { display: flex; align-items: center; gap: .6rem; flex-wrap: wrap; }
.beat-dot { width: 14px; height: 14px; border-radius: 50%; background: var(--line); }
.beat-dot.on { animation: beat .25s; }
@keyframes beat { 0% { background: var(--red); transform: scale(1.4); } }
.hint { font-size: .82rem; color: var(--ink-2); flex-basis: 100%; }
.cpr-progress { display: flex; align-items: center; gap: .8rem; margin-top: 1.2rem; font-size: .9rem; color: var(--ink-2); }
.progress { flex: 1; height: 10px; background: #e9e1d3; border-radius: 5px; overflow: hidden; }
.progress-fill { height: 100%; width: 0; background: var(--green); transition: width .15s; }

/* ---------- stroke faces ---------- */
.faces { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: .5rem 1.5rem; margin-bottom: 1.2rem; padding-bottom: 1.2rem; border-bottom: 1px solid var(--line); }
.faces figure { margin: 0; text-align: center; }
.face { width: 96px; height: 96px; }
.face .mouth { transition: d .3s; }
.faces figcaption { font-size: .82rem; color: var(--ink-2); }
.faces figcaption.warn { color: var(--red); font-weight: 600; }
.faces .btn { flex-basis: 100%; max-width: 240px; }
.fast { display: grid; grid-template-columns: repeat(4, 1fr); gap: .5rem; margin-bottom: 1.2rem; }
.fast-card { background: var(--paper); border-radius: 12px; padding: .7em; }
.fast-card:last-child { background: var(--red-soft); }
.fast-l { display: block; font-family: var(--serif); font-size: 2rem; font-weight: 700; color: var(--red); line-height: 1; }
.fast-card strong { display: block; margin-top: .2rem; }
.fast-card p { margin: .2rem 0 0; font-size: .85rem; color: var(--ink-2); }

/* ---------- bleeding ---------- */
.bleed { text-align: center; }
.arm { width: 100%; max-width: 360px; display: block; margin: 0 auto; }
.press-hand { transition: opacity .1s; }
.hold-btn {
  width: 150px; height: 150px; border-radius: 50%; border: 0; padding: 8px; margin-top: .8rem;
  background: conic-gradient(var(--green) var(--p, 0deg), #e9e1d3 0); cursor: pointer;
  user-select: none; -webkit-user-select: none; touch-action: none; -webkit-touch-callout: none;
}
.hold-ring {
  --p: 0deg;
  width: 100%; height: 100%; border-radius: 50%; display: grid; place-items: center;
  background: var(--card); font-weight: 700; transition: transform .1s;
}
.hold-btn { background: none; }
.hold-btn .hold-ring { box-shadow: 0 0 0 8px #e9e1d3; background: radial-gradient(circle, var(--card) 62%, transparent 63%), conic-gradient(var(--green) var(--p), #e9e1d3 0); }
.hold-btn.down .hold-ring { transform: scale(.94); }
.hold-btn.complete .hold-ring { color: var(--green); }

/* ---------- ORS ---------- */
.ors { display: grid; grid-template-columns: 120px 1fr; gap: 1.2rem; align-items: start; }
.jug {
  position: relative; height: 170px; border: 3px solid var(--ink); border-top: 0;
  border-radius: 0 0 22px 22px; background: linear-gradient(transparent 18%, #d7ecf7 18%);
  overflow: hidden;
}
.water { position: absolute; inset: 22% 6px 6px; display: flex; flex-wrap: wrap-reverse; align-content: flex-start; gap: 4px; padding: 4px; }
.grain { width: 14px; height: 14px; border-radius: 4px; animation: pop .25s; }
.grain.sugar { background: #fff; border: 1px solid #c9bfae; }
.grain.salt { background: #6b7d8c; border-radius: 50%; width: 10px; height: 10px; }
.jug-label { position: absolute; top: 2px; left: 0; right: 0; text-align: center; font-size: .78rem; font-weight: 700; color: var(--ink-2); }
.ors-ctrls { display: grid; gap: .7rem; }
.stepper { display: flex; justify-content: space-between; align-items: center; background: var(--card); border: 2px solid var(--line); border-radius: 12px; padding: .5em .8em; }
.stepper-label small { display: block; color: var(--ink-2); font-size: .8rem; }
.stepper-ctrl { display: flex; align-items: center; gap: .6rem; }
.stepper output { font-family: var(--serif); font-size: 1.6rem; font-weight: 700; min-width: 2ch; text-align: center; }
.round { width: 38px; height: 38px; border-radius: 50%; border: 2px solid var(--ink); background: var(--card); font-size: 1.2rem; font-weight: 700; cursor: pointer; }
.round:hover { background: var(--ink); color: #fff; }
.ors-ctrls .btn { justify-self: start; }

/* ---------- drowning ---------- */
.pool { width: 100%; display: block; border-radius: 14px; }
.wave { animation: wave 3s ease-in-out infinite; }
@keyframes wave { 50% { transform: translateX(-50px); } }
.swimmer { cursor: pointer; outline: none; }
.swimmer:hover, .swimmer:focus-visible { filter: drop-shadow(0 0 6px #fff); }
.swimmer.found { filter: drop-shadow(0 0 8px #ffeb3b); }
.sw-label { font: 700 16px var(--sans); fill: #0b3d56; }
.shout { font: 700 12px var(--sans); fill: #0b3d56; }
.splash { animation: splash .6s ease-in-out infinite alternate; }
@keyframes splash { to { transform: translateY(-6px); opacity: .5; } }
.lap { animation: lap 4s ease-in-out infinite alternate; }
@keyframes lap { to { transform: translateX(-28px); } }
.bob { animation: bob 1.6s ease-in-out infinite; }
@keyframes bob { 50% { transform: translateY(5px); } }
.sw-cards { display: grid; gap: .4rem; margin-top: .8rem; }
.sw-card { font-size: .93rem; padding: .5em .8em; }

/* ---------- habits ---------- */
.habits, .finish { max-width: 1040px; margin: 4rem auto; }
.habits h2, .finish h2 { font-size: clamp(1.8rem, 4vw, 2.6rem); }
.sub { color: var(--ink-2); margin: .4rem 0 1.6rem; font-size: 1.1rem; }
.habit-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.habit { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 1.1rem; }
.habit-icon { font-size: 1.6rem; display: block; }
.habit strong { display: block; margin: .3rem 0; }
.habit p { margin: 0; color: var(--ink-2); font-size: .93rem; }

/* ---------- finish ---------- */
.finish { scroll-margin-top: 70px; }
.all-done .finish h2 { color: var(--green); }
.finish-grid { display: grid; grid-template-columns: 1.1fr 1fr; gap: 2rem; align-items: start; }
.card {
  background: var(--ink); color: #f7f3ec; border-radius: 20px; padding: 1.4rem 1.6rem; margin-bottom: .8rem;
  box-shadow: var(--shadow);
}
.card-head { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px solid rgba(255,255,255,.2); padding-bottom: .6rem; margin-bottom: .8rem; }
.card-head strong { font-family: var(--serif); font-size: 1.25rem; }
.card-head span { font-size: .75rem; letter-spacing: .1em; text-transform: uppercase; opacity: .7; }
.card ol { margin: 0; padding-left: 1.4em; font-size: .95rem; }
.card li { margin-bottom: .45em; }
.card li::marker { color: #ff8a98; font-weight: 700; }
.reach { background: var(--card); border: 1px solid var(--line); border-radius: 20px; padding: 1.4rem 1.6rem; }
.reach h3 { font-size: 1.3rem; margin-bottom: .8rem; }
.reach h3.mt { margin-top: 1.6rem; }
.reach label { display: block; font-size: .95rem; color: var(--ink-2); }
.reach label output { font-weight: 700; color: var(--ink); font-size: 1.1rem; }
.reach input[type=range] { width: 100%; accent-color: var(--red); margin: .3rem 0 .8rem; }
.reach-n { font-family: var(--serif); font-size: clamp(2rem, 4vw, 2.8rem); font-weight: 700; color: var(--red); line-height: 1.1; }
.reach-note { margin: .3rem 0 0; color: var(--ink-2); }
.share-text { width: 100%; font: .88rem/1.45 var(--sans); border: 2px solid var(--line); border-radius: 12px; padding: .7em; background: var(--paper); resize: vertical; margin-bottom: .6rem; }

.footer { max-width: 1040px; margin: 0 auto; padding: 2rem 1.25rem 4rem; border-top: 1px solid var(--line); color: var(--ink-2); font-size: .92rem; }
.footer .fine { font-size: .8rem; }

/* ---------- emergency overlay ---------- */
.overlay { position: fixed; inset: 0; z-index: 50; background: rgba(20, 10, 10, .55); display: grid; place-items: center; padding: 1rem; }
.overlay[hidden] { display: none; }
.ov-panel { background: var(--card); border-radius: 22px; width: min(680px, 100%); max-height: calc(100vh - 2rem); display: flex; flex-direction: column; overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,.3); }
.ov-top { display: flex; justify-content: space-between; align-items: center; padding: .9rem 1.2rem; background: var(--red); color: #fff; }
.ov-close { background: rgba(255,255,255,.2); border: 0; color: #fff; width: 36px; height: 36px; border-radius: 50%; cursor: pointer; font-size: 1.1rem; }
.ov-body { padding: 1.2rem; overflow-y: auto; }
.ov-body h2 { font-size: 1.6rem; margin: .4rem 0 1rem; }
.ov-call { background: var(--red-soft); border: 2px solid var(--red); color: var(--red); border-radius: 14px; padding: .8rem 1rem; font-weight: 800; font-size: 1.25rem; }
.ov-call small { display: block; font-weight: 500; font-size: .9rem; color: var(--ink-2); }
.ov-call.slim { font-size: 1rem; margin-bottom: 1rem; }
.ov-q { font-weight: 800; font-size: 1.25rem; margin: 1.2rem 0 .6rem; }
.ov-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: .5rem; }
.ov-btn { display: flex; gap: .6rem; align-items: center; text-align: left; padding: .8rem .9rem; border-radius: 12px; border: 2px solid var(--line); background: var(--paper); cursor: pointer; font-weight: 600; }
.ov-btn span { font-size: 1.4rem; }
.ov-btn:hover { border-color: var(--red); }
.ov-back { background: none; border: 0; padding: 0; font-weight: 600; color: var(--ink-2); cursor: pointer; }
.ov-metro { display: flex; align-items: center; gap: 1rem; background: var(--paper); border-radius: 14px; padding: .8rem; margin-bottom: 1rem; }
.ov-metro p { margin: 0; font-weight: 600; }
.pulse { flex: none; width: 76px; height: 76px; border-radius: 50%; background: var(--red); color: #fff; display: grid; place-items: center; font-weight: 800; letter-spacing: .08em; animation: pulse .5454s infinite; }
@keyframes pulse { 0% { transform: scale(1.12); } 40% { transform: scale(.9); } 100% { transform: scale(.9); } }

/* ---------- responsive ---------- */
@media (max-width: 860px) {
  .lesson-body, .finish-grid { grid-template-columns: 1fr; }
  .habit-grid { grid-template-columns: 1fr 1fr; }
  .brand, .tally { display: none; }
  .dots { justify-content: flex-start; overflow-x: auto; }
}
@media (max-width: 560px) {
  body { font-size: 16px; }
  .lesson { padding: 1.3rem 1.1rem; border-radius: 18px; margin: 2.2rem auto; }
  .lesson-head { flex-direction: column; gap: .3rem; }
  .lesson-num { font-size: 2.2rem; }
  .practice { padding: 1rem; }
  .fast { grid-template-columns: 1fr 1fr; }
  .habit-grid { grid-template-columns: 1fr; }
  .cpr-main { flex-direction: column; align-items: stretch; }
  .chest { align-self: center; }
  .ors { grid-template-columns: 1fr; }
  .jug { width: 120px; justify-self: center; }
  .dot { width: 28px; height: 28px; font-size: 13px; flex: none; }
  .sort-row { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
  .pulse { animation: pulse .5454s infinite !important; } /* the CPR beat is functional, keep it */
}

/* ---------- print: just the card ---------- */
@media print {
  body { background: #fff; }
  body * { visibility: hidden; }
  .card, .card * { visibility: visible; }
  .card { position: absolute; top: 0; left: 0; width: 100%; background: #fff; color: #000; border: 2px solid #000; box-shadow: none; }
  .card li::marker { color: #000; }
}

