import puppeteer from "puppeteer-core";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
const root = process.cwd();
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css" };
const srv = http.createServer((req, res) => {
  const f = path.join(root, decodeURIComponent(req.url.split("?")[0]) === "/" ? "index.html" : req.url.split("?")[0]);
  fs.readFile(f, (e, d) => { if (e) { res.writeHead(404); res.end(); return; } res.writeHead(200, { "content-type": types[path.extname(f)] || "application/octet-stream" }); res.end(d); });
}).listen(8765);
const browser = await puppeteer.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: "new" });
const page = await browser.newPage();
const errs = [];
page.on("pageerror", (e) => errs.push(e.message));
page.on("console", (m) => m.type() === "error" && errs.push(m.text()));
const [w, hgt] = (process.env.VP || "1280x800").split("x").map(Number);
await page.setViewport({ width: w, height: hgt });
await page.goto("http://localhost:8765/", { waitUntil: "load" });
const script = process.argv[2] ? await import(path.resolve(process.argv[2])) : null;
if (script) await script.default(page);
else await page.screenshot({ path: "shot.jpg", type: "jpeg", quality: 70 });
console.log("errors:", errs);
await browser.close(); srv.close();
EOF
